contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 _number1,
        uint64 _timestamp1,
        uint256 _basefee1,
        bytes32 _hash1,
        uint64 _sequenceNumber1,
        bytes32 _batcherHash1,
        uint256 _l1FeeOverhead1,
        uint256 _l1FeeScalar1,
        uint64 _number2,
        uint64 _timestamp2,
        uint256 _basefee2,
        bytes32 _hash2,
        uint64 _sequenceNumber2,
        bytes32 _batcherHash2,
        uint256 _l1FeeOverhead2,
        uint256 _l1FeeScalar2
    ) public {
        // First, establish a known hash state via a top-level call.
        // This call may revert for non-depositor callers, so wrap it in try/catch.
        bool firstReverted;
        try c.setL1BlockValues(
            _number1,
            _timestamp1,
            _basefee1,
            _hash1,
            _sequenceNumber1,
            _batcherHash1,
            _l1FeeOverhead1,
            _l1FeeScalar1
        ) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Read the hash before the deciding call.
        bytes32 beforeHash = c.hash();

        // Deciding call: try to set the hash to _hash2.
        bool reverted;
        try c.setL1BlockValues(
            _number2,
            _timestamp2,
            _basefee2,
            _hash2,
            _sequenceNumber2,
            _batcherHash2,
            _l1FeeOverhead2,
            _l1FeeScalar2
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bytes32 afterHash = c.hash();

        // If the deciding call succeeds, hash() must equal the passed _hash2.
        // If it reverts, hash() must remain equal to the beforeHash value.
        assert(reverted ? afterHash == beforeHash : afterHash == _hash2);
    }
}

